package io.github.diodeme.ji.ai;

import java.util.List;

/** Complete provider-neutral result of one non-streaming model request. */
public record ModelResponse(String responseId, List<Content> content, Usage usage, ModelStreamEvent.StopReason stopReason) {
    public ModelResponse {
        if (responseId == null || responseId.isBlank()) throw new IllegalArgumentException("responseId must not be blank");
        content = List.copyOf(content);
        if (usage == null) throw new IllegalArgumentException("usage must not be null");
        if (stopReason == null) throw new IllegalArgumentException("stopReason must not be null");
    }
}
